
DROP TABLE IF EXISTS airfields;
CREATE TABLE airfields (
  id SERIAL PRIMARY KEY,
  osm_id BIGINT,
  name TEXT,
  icao TEXT,
  kind TEXT NOT NULL,
  ref TEXT,
  width_m DOUBLE PRECISION,
  geom geometry(Geometry, 4326) NOT NULL
);


SELECT osm_id, name, icao, 'centerpoint', NULL, NULL, ST_PointOnSurface(geom)
FROM airfields WHERE kind = 'boundary';

CREATE INDEX airfields_geom_idx ON airfields USING GIST (geom);
SELECT kind, count(*) FROM airfields GROUP BY kind;